-- Phase 4: versioned design.md documents per board, generated by the worker's `spec` job.

alter table public.jobs drop constraint if exists jobs_kind_check;
alter table public.jobs add constraint jobs_kind_check check (kind in ('analyze', 'embed', 'cluster', 'spec'));
-- Job options, e.g. {"cluster_ids": [...], "section": "palette"} for a spec job.
alter table public.jobs add column if not exists params jsonb not null default '{}'::jsonb;

create table public.design_specs (
  id         uuid primary key default gen_random_uuid(),
  board_id   uuid not null references public.boards (id) on delete cascade,
  user_id    uuid not null default auth.uid() references auth.users (id) on delete cascade,
  version    integer not null,
  markdown   text not null,
  -- generated: full AI run · section: one section regenerated · edit: saved by the user ·
  -- draft: built from stored analyses without an LLM (no key / quota)
  kind       text not null check (kind in ('generated', 'section', 'edit', 'draft')),
  -- reference ids cited, cluster ids used, model, section name…
  sources    jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now(),
  unique (board_id, version)
);
create index design_specs_board_idx on public.design_specs (board_id, version desc);

alter table public.design_specs enable row level security;
create policy "own design specs" on public.design_specs
  for all using (auth.uid() = user_id) with check (
    auth.uid() = user_id
    and exists (select 1 from public.boards b where b.id = board_id and b.user_id = auth.uid())
  );
